366	/** Where migrated data lands on the target, for the completion notice. */
367	export function migrationWorkDir(migrationId: string): string {
368	  return `/root/nxeon-migrations/${migration_id_safe(migrationId)}`;
369	}
370	
371	function migration_id_safe(id: string): string {
372	  return /^[A-Za-z0-9_-]{1,64}$/.test(id) ? id : "invalid";
373	}
