1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { encryptSecret } from "./crypto-box";
7	import { checkRateLimit } from "./rate-limit";
8	
9	/**
10	 * VPS migration — pull a customer's files + databases from another provider's
11	 * VPS onto their new Nxeon server. The customer supplies SSH credentials for the
12	 * SOURCE box; we only ever verify ownership of the TARGET (Nxeon) server.
13	 *
14	 * All source secrets (the SSH password and each database password) are encrypted
15	 * at rest with the shared AES-256-GCM box in lib/crypto-box.ts (`encryptSecret`),
16	 * the SAME helper used for mailbox/BYOK secrets. They are CLEARED by the worker
17	 * (worker/migrate.ts) the moment the migration finishes — success or failure —
18	 * so a completed Migration row never retains usable credentials. Nothing here
19	 * ever returns a decrypted secret (or the ciphertext) to the client.
20	 *
21	 * The heavy lifting runs in the `MIGRATE` worker job; this module only validates
22	 * input, encrypts secrets, records the Migration row and enqueues the job.
23	 */
24	
25	// ---- Input shapes (mirrors the Migration.items Json) ------------------------
26	
27	export type MigrateDatabaseInput = {
28	  engine: "mysql" | "postgres";
29	  name: string;
30	  user: string;
31	  password: string;
32	};
33	
34	export type CreateMigrationInput = {
35	  serverId: string; // target Nxeon server (must be owned by the caller)
36	  sourceHost: string; // FQDN or IP of the source VPS
37	  sourcePort?: number; // SSH port, default 22
38	  sourceUser?: string; // SSH user, default "root"
39	  sourcePassword: string; // SSH password for the source box
40	  paths?: string[]; // file paths to copy from the source
41	  databases?: MigrateDatabaseInput[]; // optional DB dumps to move
42	};
43	
44	// ---- Client-safe row shapes (NEVER include secrets) -------------------------
45	
46	export type MigrationDatabaseView = {
47	  engine: string;
48	  name: string;
49	  user: string;
50	};
51	
52	export type MigrationRow = {
53	  id: string;
54	  serverId: string;
55	  serverName: string | null;
56	  sourceHost: string;
57	  sourcePort: number;
58	  sourceUser: string;
59	  paths: string[];
60	  databases: MigrationDatabaseView[];
61	  status: string;
62	  progress: number;
63	  step: string | null;
64	  log: string | null;
65	  lastError: string | null;
66	  createdAt: string;
67	  finishedAt: string | null;
68	};
69	
70	// ---- Validation -------------------------------------------------------------
71	
72	// Hostname/FQDN (RFC-1123-ish) or IPv4 literal. Deliberately permissive on IPv6
73	// (a bracketed/colon form is accepted) — the worker's SSH layer does the final
74	// resolution; this only rejects obvious junk before we store anything.
75	const HOST_RE =
76	  /^(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?|\d{1,3}(?:\.\d{1,3}){3}|\[?[0-9a-fA-F:]+\]?)$/;
77	const DEFAULT_PATHS = ["/var/www", "/home"];
78	const MAX_PATHS = 40;
79	const MAX_DATABASES = 25;
80	
81	function cleanPaths(paths: string[] | undefined): string[] {
82	  const list = (paths && paths.length ? paths : DEFAULT_PATHS)
83	    .map((p) => p.trim())
84	    .filter((p) => p.length > 0 && p.startsWith("/") && !p.includes("\0"));
85	  // De-dupe while preserving order.
86	  return [...new Set(list)].slice(0, MAX_PATHS);
87	}
88	
89	async function ownedTargetServer(serverId: string) {
90	  const user = await requireUser();
91	  const server = await db.server.findUnique({ where: { id: serverId } });
92	  if (!server) throw new Error("Not found");
93	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
94	  return { user, server };
95	}
96	
97	function toRow(
98	  m: {
99	    id: string;
100	    serverId: string;
101	    sourceHost: string;
102	    sourcePort: number;
103	    sourceUser: string;
104	    items: unknown;
105	    status: string;
106	    progress: number;
107	    step: string | null;
108	    log: string | null;
109	    lastError: string | null;
110	    createdAt: Date;
111	    finishedAt: Date | null;
112	  },
113	  server: { hostname: string; label: string | null } | null
114	): MigrationRow {
115	  const items = (m.items ?? {}) as {
116	    paths?: string[];
117	    databases?: { engine?: string; name?: string; user?: string }[];
118	  };
119	  return {
120	    id: m.id,
121	    serverId: m.serverId,
122	    // Migration has no Prisma relation to Server (serverId is a plain FK), so the
123	    // caller resolves the server row and passes it in.
124	    serverName: server ? server.label || server.hostname : null,
125	    sourceHost: m.sourceHost,
126	    sourcePort: m.sourcePort,
127	    sourceUser: m.sourceUser,
128	    paths: Array.isArray(items.paths) ? items.paths : [],
129	    // Strip every DB secret (passEnc) — expose only non-sensitive fields.
130	    databases: Array.isArray(items.databases)
131	      ? items.databases.map((d) => ({
132	          engine: String(d.engine ?? ""),
133	          name: String(d.name ?? ""),
134	          user: String(d.user ?? ""),
135	        }))
136	      : [],
137	    status: m.status,
138	    progress: m.progress,
139	    step: m.step,
140	    log: m.log,
141	    lastError: m.lastError,
142	    createdAt: m.createdAt.toISOString(),
143	    finishedAt: m.finishedAt ? m.finishedAt.toISOString() : null,
144	  };
145	}
146	
147	// ---- Actions ----------------------------------------------------------------
148	
149	/**
150	 * Start a migration onto one of the caller's Nxeon servers. Verifies TARGET
151	 * ownership, validates the source connection details, encrypts every source
152	 * secret, writes the Migration row (PENDING) and enqueues a MIGRATE job. Returns
153	 * the new migration id; never returns any secret.
154	 */
155	export async function createMigration(
156	  input: CreateMigrationInput
157	): Promise<{ error?: string; id?: string }> {
158	  const { user, server } = await ownedTargetServer(input.serverId);
159	
160	  // Rate-limit: a few migrations per user per 10 minutes is plenty and stops
161	  // credential-stuffing the wizard against arbitrary source hosts.
162	  const rl = checkRateLimit(`migrate:create:${user.id}`, { max: 5, windowMs: 10 * 60 * 1000 });
163	  if (!rl.ok) {
164	    return { error: `Too many migrations started — please wait ${rl.retryAfterSec}s and try again.` };
165	  }
166	
167	  const host = (input.sourceHost ?? "").trim();
168	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
169	    return { error: "Enter a valid source host — an IP address or domain name." };
170	  }
171	
172	  const port = input.sourcePort ?? 22;
173	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
174	    return { error: "SSH port must be between 1 and 65535." };
175	  }
176	
177	  const sourceUser = (input.sourceUser ?? "root").trim();
178	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
179	    return { error: "Enter the SSH username on the source server." };
180	  }
181	
182	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
183	    return { error: "Enter the SSH password for the source server." };
184	  }
185	
186	  const paths = cleanPaths(input.paths);
187	
188	  // Validate + encrypt each database. Passwords go straight into passEnc; the
189	  // plaintext never lands in the row.
190	  const databases: { engine: string; name: string; user: string; passEnc: string }[] = [];
191	  for (const d of input.databases ?? []) {
192	    if (databases.length >= MAX_DATABASES) break;
193	    const engine = d.engine;
194	    if (engine !== "mysql" && engine !== "postgres") {
195	      return { error: "Database engine must be MySQL or PostgreSQL." };
196	    }
197	    const name = (d.name ?? "").trim();
198	    const dbUser = (d.user ?? "").trim();
199	    if (!name || name.length > 128) return { error: "Enter a valid database name." };
200	    if (!dbUser || dbUser.length > 128) return { error: "Enter a valid database user." };
201	    databases.push({
202	      engine,
203	      name,
204	      user: dbUser,
205	      passEnc: encryptSecret(d.password ?? ""),
206	    });
207	  }
208	
209	  const migration = await db.migration.create({
210	    data: {
211	      userId: user.id,
212	      serverId: server.id,
213	      sourceHost: host,
214	      sourcePort: port,
215	      sourceUser,
216	      sourcePasswordEnc: encryptSecret(input.sourcePassword),
217	      items: { paths, databases },
218	      status: "PENDING",
219	      progress: 0,
220	      step: "Queued",
221	    },
222	  });
223	
224	  // Enqueue the worker job. serverId ties the job to the target (cascade delete +
225	  // traceability); the handler loads everything else from payload.migrationId.
226	  await db.job.create({
227	    data: {
228	      type: "MIGRATE",
229	      serverId: server.id,
230	      payload: { migrationId: migration.id },
231	    },
232	  });
233	
234	  await db.auditLog.create({
235	    data: {
236	      userId: user.id,
237	      action: "migration.create",
238	      detail: `${migration.id} ${sourceUser}@${host}:${port} -> ${server.hostname} (${paths.length} paths, ${databases.length} dbs)`,
239	    },
240	  });
241	
242	  revalidatePath("/dashboard/migrate");
243	  return { id: migration.id };
244	}
245	
246	/** The current user's migrations, newest first, WITHOUT any decrypted secrets. */
247	export async function listMigrations(): Promise<MigrationRow[]> {
248	  const user = await requireUser();
249	  const rows = await db.migration.findMany({
250	    where: { userId: user.id },
251	    orderBy: { createdAt: "desc" },
252	  });
253	  const serverIds = [...new Set(rows.map((r) => r.serverId))];
254	  const servers = await db.server.findMany({
255	    where: { id: { in: serverIds } },
256	    select: { id: true, hostname: true, label: true },
257	  });
258	  const byId = new Map(servers.map((s) => [s.id, s]));
259	  return rows.map((m) => toRow(m, byId.get(m.serverId) ?? null));
260	}
261	
262	/**
263	 * Fetch a single migration for progress polling. Owner-only. Never returns the
264	 * encrypted source password or any DB passEnc.
265	 */
266	export async function getMigration(id: string): Promise<MigrationRow | null> {
267	  const user = await requireUser();
268	  const m = await db.migration.findUnique({ where: { id } });
269	  if (!m) return null;
270	  if (m.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
271	  const server = await db.server.findUnique({
272	    where: { id: m.serverId },
273	    select: { id: true, hostname: true, label: true },
274	  });
275	  return toRow(m, server);
276	}
