352	function MigrationProgress({ id, onDone }: { id: string; onDone: () => void }) {
353	  const [row, setRow] = useState<MigrationRow | null>(null);
354	  const [error, setError] = useState<string | null>(null);
355	
356	  useEffect(() => {
357	    let cancelled = false;
358	    let timer: ReturnType<typeof setTimeout>;
359	
360	    async function poll() {
361	      try {
362	        const m = await getMigration(id);
363	        if (cancelled) return;
364	        setRow(m);
365	        if (m && (m.status === "DONE" || m.status === "FAILED")) return; // stop polling
366	      } catch {
367	        if (!cancelled) setError("Lost connection while checking progress.");
368	      }
369	      if (!cancelled) timer = setTimeout(poll, 3000);
370	    }
371	    poll();
372	    return () => {
373	      cancelled = true;
374	      clearTimeout(timer);
375	    };
376	  }, [id]);
