343	      await destroyVm(conn, server.vmid);
344	    } catch (e: any) {
345	      // VM may never have been created; only swallow "does not exist"
346	      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
347	    }
348	    // Best-effort: remove the per-server cloud-init snippet
349	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
350	  }
351	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
352	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
353	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
354	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
355	  // diskName and keep billing forever. Remove them and notify the owner. (The
356	  // reinstall guard already blocks the accidental case; a full server delete is an
357	  // intentional teardown, so we drop the volumes with it.)
358	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
359	  if (orphanVolumes.length > 0) {
360	    await db.volume.deleteMany({ where: { serverId: server.id } });
361	    for (const v of orphanVolumes) {
362	      await notify(
363	        v.userId,
364	        `Volume "${v.name}" was removed`,
365	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
366	        "/dashboard/volumes",
367	      ).catch(() => {});
368	    }
369	  }
370	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
371	  // server.delete cascade removes THIS running Job row — the success-path
372	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
373	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
374	  await db.server.delete({ where: { id: server.id } });
375	  if (!SANDBOX) await syncPortForwards();
376	}
