672	/**
673	 * Reverse a money side-effect that a job committed up-front but never delivered.
674	 * Server actions charge/credit the wallet before enqueuing the worker job (so the
675	 * UI reflects the change immediately); if the job then fails terminally the money
676	 * must be unwound or the customer is charged for a resize that never happened
677	 * (up) or keeps a downgrade credit for hardware they still have (down).
678	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
679	 * double-reverse.
680	 */
681	async function reconcileFailedJob(job: Job) {
682	  if (job.type !== "RESIZE") return;
683	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
684	  const cents = p.prorateCents ?? 0;
685	  if (cents <= 0 || !job.serverId) return;
686	
687	  // Idempotency: skip if we already reversed this exact job.
688	  const already = await db.auditLog.findFirst({
689	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
690	  });
691	  if (already) return;
692	
693	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
694	  if (!server) return;
695	
696	  try {
697	    if (p.direction === "up") {
698	      // Upgrade charge never delivered → refund the prorated charge.
699	      await db.$transaction([
700	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
701	        db.walletTransaction.create({
702	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
703	        }),
704	      ]);
705	    } else if (p.direction === "down") {
706	      // Downgrade credit was given but hardware unchanged → claw the credit back.
707	      // Guarded so it can never drive the balance negative; if the customer already
708	      // spent it, we log and leave it (best-effort — they keep a small windfall).
709	      await db.$transaction(async (tx) => {
710	        await debitWallet(tx, server.userId, cents);
711	        await tx.walletTransaction.create({
712	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
713	        });
714	      });
715	    }
716	    await db.auditLog.create({
717	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
718	    });
719	  } catch (e: any) {
720	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
721	    await db.auditLog.create({
722	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
723	    }).catch(() => {});
724	  }
725	}
