784	/**
785	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
786	 * killed worker leaves a job RUNNING forever, which permanently blocks the
787	 * server's "one in-flight job" guard and strands it in a transitional state.
788	 */
789	async function reapStuckJobs() {
790	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
791	  for (const job of stuck) {
792	    const retriable = job.attempts < MAX_ATTEMPTS;
793	    await db.job.update({
794	      where: { id: job.id },
795	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
796	    });
797	    if (!retriable) {
798	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
799	      if (job.serverId) {
800	        const s = await db.server.findUnique({ where: { id: job.serverId } });
801	        if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
802	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
803	        }
804	      }
805	    }
806	    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
807	  }
808	}
