811	  console.log("[worker] Nxeon provisioning worker starting");
812	  await reapStuckJobs();
813	  if (!SANDBOX) await syncPortForwards();
814	  console.log("[worker] port forwards synced");
815	
816	  let lastSweep = 0;
817	  let lastIpSync = 0;
818	  let lastGameSweep = 0;
819	  let lastGeoSweep = 0;
