/**
 * READ-ONLY source detection for the migration wizard.
 *
 * Given the SSH credentials for a customer's OLD (source) VPS, SSH in and
 * auto-detect what is worth migrating — web roots / codebases, home directories
 * and databases — so the wizard can present a pre-checked checklist instead of
 * making a beginner type paths and DB names by hand.
 *
 * This is a plain (non-"use server") module so the migration server actions can
 * import it, exactly like lib/sftp.ts. It connects DIRECTLY from our server to
 * the source over SSH (the same outbound-SSH capability the file manager already
 * uses), runs a handful of strictly READ-ONLY probes, and returns structured
 * JSON. It NEVER writes to, installs on, or otherwise mutates the source.
 *
 * ── SECURITY (mirrors worker/migrate-real.ts) ────────────────────────────────
 *  1. STRICT ALLOWLIST VALIDATION. Host / port / SSH user / (optional) DB user
 *     are validated against the same shell-inert allowlist regexes used by the
 *     real migration engine before they are used. We reject — never sanitize.
 *  2. NO UNTRUSTED VALUE IS EVER INTERPOLATED INTO A COMMAND. The filesystem /
 *     engine probe is a single FIXED shell script containing no caller input:
 *     it enumerates candidate roots, globs, parses vhost configs, sizes and
 *     type-sniffs entirely on the source and only PRINTS tagged lines that we
 *     read back. Paths discovered on the source are therefore never fed back
 *     into a command we build — closing the "malicious vhost root" injection
 *     hole.
 *  3. SECRETS NEVER TOUCH A COMMAND STRING OR ARGV. The optional database
 *     password is streamed into the remote shell's STDIN, `read` into a shell
 *     variable and exported as the engine's password env var (MYSQL_PWD /
 *     PGPASSWORD). It is never an argv token, never written to disk, and never
 *     interpolated into the command string.
 *  4. READ-ONLY + BOUNDED. Every probe is read-only (du/ls/grep/SELECT); each
 *     `du` is wrapped in `timeout`; the whole detection is bounded by an overall
 *     deadline and per-exec timeouts, and output is size-capped.
 *
 * In SANDBOX (staging) mode NO SSH connection is opened — realistic synthetic
 * results are returned so the whole wizard works end to end on staging.
 */
import { Client, type ClientChannel } from "ssh2";
import { SANDBOX } from "./sandbox";

// ---- Strict allowlist validators (identical to worker/migrate-real.ts) ------
// Kept local so this read-only scanner is self-contained. These charsets are
// shell-inert: no quotes, spaces, metachars or newlines.
const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
const IDENT_RE = /^[A-Za-z0-9_]{1,64}$/; // DB user (only used if we list DBs)

function validHost(h: string): boolean {
  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
}

// ---- Timeouts / caps --------------------------------------------------------
const CONNECT_TIMEOUT_MS = 15_000;
const PROBE_TIMEOUT_MS = 60_000; // the fixed filesystem/engine probe
const DB_TIMEOUT_MS = 30_000; // optional DB name/size listing
const OVERALL_TIMEOUT_MS = 90_000; // hard ceiling for the whole detection
const MAX_OUTPUT_BYTES = 256 * 1024; // cap probe stdout
const MAX_WEB_ROOTS = 40;
const MAX_HOMES = 40;
const MAX_DATABASES = 60;

// ---- Public result shapes (contain NO secrets) ------------------------------
export type DetectedWebRoot = {
  path: string;
  /** wordpress | laravel | django | php | node | other */
  type: string;
  sizeBytes: number | null;
  sizeLabel: string;
};
export type DetectedHome = {
  path: string;
  sizeBytes: number | null;
  sizeLabel: string;
};
export type DetectedDatabase = {
  engine: "mysql" | "postgres";
  name: string;
  user: string;
  sizeBytes: number | null;
  sizeLabel: string;
};
export type DetectedEngine = {
  engine: "mysql" | "postgres";
  /** binary present on the source */
  present: boolean;
  /** listening on its default port (3306 / 5432) */
  listening: boolean;
  /** whether we listed databases with the customer's creds */
  credentialsUsed: boolean;
  note?: string;
};
export type DetectResult = {
  webRoots: DetectedWebRoot[];
  homes: DetectedHome[];
  databases: DetectedDatabase[];
  engines: DetectedEngine[];
  notes: string[];
};

export type DetectInput = {
  host: string;
  port: number;
  user: string;
  password: string;
  /** optional — only used to LIST database names + sizes */
  dbUser?: string;
  dbPassword?: string;
};

// ---- Helpers ----------------------------------------------------------------
function humanSize(bytes: number | null): string {
  if (bytes == null || !Number.isFinite(bytes) || bytes < 0) return "—";
  const units = ["B", "KB", "MB", "GB", "TB"];
  let n = bytes;
  let i = 0;
  while (n >= 1024 && i < units.length - 1) {
    n /= 1024;
    i++;
  }
  return `${n >= 10 || i === 0 ? Math.round(n) : n.toFixed(1)} ${units[i]}`;
}

function webRootLabel(type: string): string {
  switch (type) {
    case "wordpress":
      return "WordPress";
    case "laravel":
      return "Laravel";
    case "django":
      return "Django";
    case "php":
      return "PHP app";
    case "node":
      return "Node app";
    default:
      return "Website / files";
  }
}
export { webRootLabel };

/** Run a fixed remote command, capture stdout/stderr, enforce a timeout + cap. */
function execRemote(conn: Client, cmd: string, timeoutMs: number): Promise<{ code: number; stdout: string; stderr: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      let capped = false;
      const timer = setTimeout(() => {
        try {
          stream.close();
        } catch {
          /* ignore */
        }
        reject(new Error("source probe timed out"));
      }, timeoutMs);
      stream
        .on("close", (code: number) => {
          clearTimeout(timer);
          resolve({ code: code ?? 0, stdout, stderr });
        })
        .on("data", (d: Buffer) => {
          if (capped) return;
          stdout += d.toString("utf8");
          if (stdout.length > MAX_OUTPUT_BYTES) {
            stdout = stdout.slice(0, MAX_OUTPUT_BYTES);
            capped = true;
          }
        })
        .stderr.on("data", (d: Buffer) => {
          if (stderr.length < 4096) stderr += d.toString("utf8");
        });
    });
  });
}

/**
 * Run a fixed remote command and stream `input` into its STDIN — used to hand a
 * database password to the remote shell without it ever appearing as an argv
 * token, in the command string, or on disk.
 */
function execRemoteInput(conn: Client, cmd: string, input: string, timeoutMs: number): Promise<{ code: number; stdout: string; stderr: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      const timer = setTimeout(() => {
        try {
          stream.close();
        } catch {
          /* ignore */
        }
        reject(new Error("source database probe timed out"));
      }, timeoutMs);
      stream
        .on("close", (code: number) => {
          clearTimeout(timer);
          resolve({ code: code ?? 0, stdout, stderr });
        })
        .on("data", (d: Buffer) => {
          if (stdout.length < MAX_OUTPUT_BYTES) stdout += d.toString("utf8");
        })
        .stderr.on("data", (d: Buffer) => {
          if (stderr.length < 4096) stderr += d.toString("utf8");
        });
      stream.end(input);
    });
  });
}

function connectSource(host: string, port: number, user: string, password: string): Promise<Client> {
  return new Promise((resolve, reject) => {
    const conn = new Client();
    let settled = false;
    conn.on("ready", () => {
      if (settled) return;
      settled = true;
      resolve(conn);
    });
    conn.on("error", (e) => {
      if (settled) return;
      settled = true;
      reject(e instanceof Error ? e : new Error(String(e)));
    });
    conn.connect({
      host,
      port,
      username: user,
      password,
      readyTimeout: CONNECT_TIMEOUT_MS,
      // Password auth only for the source probe (validated user + streamed pass).
      tryKeyboard: false,
    });
  });
}

// ── The FIXED filesystem + engine probe. Contains NO caller input. ───────────
// It enumerates candidate doc roots, /home/* + /root, parses nginx/apache vhost
// roots, sizes each with a time-bounded `du`, and type-sniffs by signature
// files, printing tab-separated tagged lines. All globbing/parsing happens on
// the source; we only READ the output, so discovered paths are never fed back
// into another command.
const PROBE_SCRIPT = String.raw`
LC_ALL=C
DU() { timeout 20 du -sb "$1" 2>/dev/null | cut -f1; }
emit_web() {
  d="$1"
  [ -d "$d" ] || return 0
  t=other
  if [ -f "$d/wp-config.php" ]; then t=wordpress
  elif [ -f "$d/artisan" ] && [ -f "$d/.env" ]; then t=laravel
  elif [ -f "$d/manage.py" ]; then t=django
  elif [ -f "$d/composer.json" ]; then t=php
  elif [ -f "$d/package.json" ]; then t=node
  fi
  sz=$(DU "$d"); [ -n "$sz" ] || sz=0
  printf 'WEB\t%s\t%s\t%s\n' "$t" "$sz" "$d"
}
# candidate doc roots
CANDS=""
for d in /var/www /var/www/html /usr/share/nginx/html /srv/www; do
  [ -d "$d" ] && CANDS="$CANDS
$d"
done
for d in /home/*/public_html; do
  [ -d "$d" ] && CANDS="$CANDS
$d"
done
# nginx / apache document roots (config values live on the source; we only read)
ROOTS=$( { grep -rhoE '^[[:space:]]*root[[:space:]]+[^;]+;' /etc/nginx 2>/dev/null | sed -E 's/^[[:space:]]*root[[:space:]]+//; s/;[[:space:]]*$//'; grep -rhoE 'DocumentRoot[[:space:]]+[^[:space:]]+' /etc/apache2 /etc/httpd 2>/dev/null | sed -E 's/DocumentRoot[[:space:]]+//'; } 2>/dev/null | tr -d '"'"'"'"' )
for d in $ROOTS; do
  case "$d" in
    /*) CANDS="$CANDS
$d" ;;
  esac
done
printf '%s\n' "$CANDS" | awk 'NF' | sort -u | head -n 60 | while IFS= read -r d; do
  emit_web "$d"
done
# home directories
for d in /home/* /root; do
  [ -d "$d" ] || continue
  sz=$(DU "$d"); [ -n "$sz" ] || sz=0
  printf 'HOME\t%s\t%s\n' "$sz" "$d"
done
# database engines: binaries present
for b in mysql mariadb psql mysqld postgres; do
  command -v "$b" >/dev/null 2>&1 && printf 'BIN\t%s\n' "$b"
done
# listening ports (ss or netstat, whichever exists)
LISTEN=$( (ss -ltn 2>/dev/null || netstat -ltn 2>/dev/null) )
printf '%s\n' "$LISTEN" | grep -qE '[:.]3306[[:space:]]' && printf 'PORT\tmysql\n'
printf '%s\n' "$LISTEN" | grep -qE '[:.]5432[[:space:]]' && printf 'PORT\tpostgres\n'
`;

/** System schemas we never present as migratable databases. */
const MYSQL_SYSTEM_DBS = new Set(["information_schema", "mysql", "performance_schema", "sys"]);
const PG_SYSTEM_DBS = new Set(["template0", "template1", "postgres"]);

/**
 * Detect what to migrate on the source. READ-ONLY. Throws only on a hard failure
 * (e.g. cannot connect / authenticate); partial-probe failures degrade to notes.
 */
export async function detectSource(input: DetectInput): Promise<DetectResult> {
  const host = (input.host ?? "").trim();
  const port = input.port;
  const user = (input.user ?? "").trim();
  const password = input.password ?? "";

  // Fail-closed validation (same allowlist as the real engine).
  if (!validHost(host)) throw new Error("Enter a valid source host — an IP address or domain name.");
  if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error("SSH port must be between 1 and 65535.");
  if (!USER_RE.test(user)) throw new Error("The SSH username contains unsupported characters.");
  if (!password) throw new Error("Enter the SSH password for the source server.");

  // ── SANDBOX: return realistic synthetic detection, no SSH. ──
  if (SANDBOX) return synthResult(host, !!(input.dbPassword && input.dbPassword.length));

  const notes: string[] = [];
  let conn: Client | null = null;
  // Overall hard deadline: if anything hangs past this, tear the connection down.
  let deadline: ReturnType<typeof setTimeout> | null = null;
  const overall = new Promise<never>((_, reject) => {
    deadline = setTimeout(() => {
      try {
        conn?.end();
      } catch {
        /* ignore */
      }
      reject(new Error("Detection timed out — the source server took too long to respond."));
    }, OVERALL_TIMEOUT_MS);
  });

  try {
    return await Promise.race([
      (async (): Promise<DetectResult> => {
        conn = await connectSource(host, port, user, password);

        // 1) Fixed filesystem + engine probe (no caller input).
        const probe = await execRemote(conn, PROBE_SCRIPT, PROBE_TIMEOUT_MS);
        const { webRoots, homes, enginePresent, enginePorts } = parseProbe(probe.stdout);

        // 2) Optional: list database names + sizes using the customer's creds.
        const engines: DetectedEngine[] = [];
        const databases: DetectedDatabase[] = [];
        const dbUser = (input.dbUser ?? "root").trim() || "root";
        const dbPassword = input.dbPassword ?? "";
        const dbUserValid = IDENT_RE.test(dbUser);

        for (const engine of ["mysql", "postgres"] as const) {
          const present = enginePresent.has(engine);
          const listening = enginePorts.has(engine);
          if (!present && !listening) continue;
          const eng: DetectedEngine = { engine, present, listening, credentialsUsed: false };

          if (dbPassword && dbUserValid) {
            try {
              const found = await listDatabases(conn, engine, dbUser, dbPassword);
              eng.credentialsUsed = true;
              for (const d of found) {
                if (databases.length >= MAX_DATABASES) break;
                databases.push(d);
              }
              if (found.length === 0) eng.note = "Connected, but found no user databases.";
            } catch (e: any) {
              eng.note = "Detected, but could not list databases with the credentials given.";
              notes.push(`${engine === "mysql" ? "MySQL/MariaDB" : "PostgreSQL"}: ${String(e?.message ?? e).slice(0, 140)}`);
            }
          } else {
            eng.note = dbPassword
              ? "Database user looks invalid — provide a valid DB user to include databases."
              : `${engine === "mysql" ? "MySQL/MariaDB" : "PostgreSQL"} detected — add a database password to include databases.`;
          }
          engines.push(eng);
        }

        if (!webRoots.length && !homes.length && !engines.length) {
          notes.push("We couldn't auto-detect much on this server — you can still add paths manually.");
        }

        return {
          webRoots: webRoots.slice(0, MAX_WEB_ROOTS),
          homes: homes.slice(0, MAX_HOMES),
          databases,
          engines,
          notes,
        };
      })(),
      overall,
    ]);
  } finally {
    if (deadline) clearTimeout(deadline);
    try {
      conn?.end();
    } catch {
      /* best-effort */
    }
  }
}

// ---- Probe output parsing ---------------------------------------------------
function parseProbe(stdout: string): {
  webRoots: DetectedWebRoot[];
  homes: DetectedHome[];
  enginePresent: Set<"mysql" | "postgres">;
  enginePorts: Set<"mysql" | "postgres">;
} {
  const webRoots: DetectedWebRoot[] = [];
  const homes: DetectedHome[] = [];
  const enginePresent = new Set<"mysql" | "postgres">();
  const enginePorts = new Set<"mysql" | "postgres">();
  const seenWeb = new Set<string>();
  const seenHome = new Set<string>();

  for (const raw of stdout.split("\n")) {
    const line = raw.replace(/\r$/, "");
    if (!line) continue;
    const parts = line.split("\t");
    const tag = parts[0];
    if (tag === "WEB" && parts.length >= 4) {
      const type = parts[1] || "other";
      const sizeBytes = toBytes(parts[2]);
      const path = parts.slice(3).join("\t");
      if (!path.startsWith("/") || seenWeb.has(path)) continue;
      seenWeb.add(path);
      webRoots.push({ path, type, sizeBytes, sizeLabel: humanSize(sizeBytes) });
    } else if (tag === "HOME" && parts.length >= 3) {
      const sizeBytes = toBytes(parts[1]);
      const path = parts.slice(2).join("\t");
      if (!path.startsWith("/") || seenHome.has(path)) continue;
      seenHome.add(path);
      homes.push({ path, sizeBytes, sizeLabel: humanSize(sizeBytes) });
    } else if (tag === "BIN") {
      const b = parts[1] ?? "";
      if (b === "mysql" || b === "mysqld" || b === "mariadb") enginePresent.add("mysql");
      if (b === "psql" || b === "postgres") enginePresent.add("postgres");
    } else if (tag === "PORT") {
      if (parts[1] === "mysql") enginePorts.add("mysql");
      if (parts[1] === "postgres") enginePorts.add("postgres");
    }
  }
  // Sort largest-first so the most important data is at the top of the checklist.
  webRoots.sort((a, b) => (b.sizeBytes ?? 0) - (a.sizeBytes ?? 0));
  homes.sort((a, b) => (b.sizeBytes ?? 0) - (a.sizeBytes ?? 0));
  return { webRoots, homes, enginePresent, enginePorts };
}

function toBytes(s: string | undefined): number | null {
  if (!s) return null;
  const n = Number(s.trim());
  return Number.isFinite(n) && n >= 0 ? n : null;
}

/**
 * List database names + sizes. The password is streamed via STDIN and `read`
 * into a shell var, then exported as the engine's password env var — never an
 * argv token, never in the command string, never on disk. Only the validated
 * DB user is interpolated into the (otherwise fixed) command.
 */
async function listDatabases(conn: Client, engine: "mysql" | "postgres", dbUser: string, dbPassword: string): Promise<DetectedDatabase[]> {
  if (engine === "mysql") {
    // MYSQL_PWD read from STDIN; -N -B => tab-separated, no headers.
    const sql =
      "SELECT s.schema_name, IFNULL(ROUND(SUM(t.data_length+t.index_length)),0) " +
      "FROM information_schema.schemata s " +
      "LEFT JOIN information_schema.tables t ON t.table_schema = s.schema_name " +
      "GROUP BY s.schema_name";
    const cmd = `IFS= read -r MYSQL_PWD; export MYSQL_PWD; mysql -u ${dbUser} -h 127.0.0.1 -N -B -e "${sql}"`;
    const r = await execRemoteInput(conn, cmd, `${dbPassword}\n`, DB_TIMEOUT_MS);
    if (r.code !== 0) throw new Error(oneLine(r.stderr) || `mysql exited ${r.code}`);
    const out: DetectedDatabase[] = [];
    for (const line of r.stdout.split("\n")) {
      const [name, size] = line.replace(/\r$/, "").split("\t");
      if (!name || MYSQL_SYSTEM_DBS.has(name)) continue;
      const sizeBytes = toBytes(size);
      out.push({ engine, name, user: dbUser, sizeBytes, sizeLabel: humanSize(sizeBytes) });
    }
    return out;
  }
  // postgres: PGPASSWORD read from STDIN; -A -t unaligned tuples, '\t' field sep.
  const sql = "SELECT datname, pg_database_size(datname) FROM pg_database WHERE datistemplate = false";
  const cmd = `IFS= read -r PGPASSWORD; export PGPASSWORD; psql -h 127.0.0.1 -U ${dbUser} -A -t -F '\t' -c "${sql}" postgres`;
  const r = await execRemoteInput(conn, cmd, `${dbPassword}\n`, DB_TIMEOUT_MS);
  if (r.code !== 0) throw new Error(oneLine(r.stderr) || `psql exited ${r.code}`);
  const out: DetectedDatabase[] = [];
  for (const line of r.stdout.split("\n")) {
    const [name, size] = line.replace(/\r$/, "").split("\t");
    if (!name || PG_SYSTEM_DBS.has(name)) continue;
    const sizeBytes = toBytes(size);
    out.push({ engine, name, user: dbUser, sizeBytes, sizeLabel: humanSize(sizeBytes) });
  }
  return out;
}

function oneLine(s: string): string {
  return (s || "").split("\n").map((l) => l.trim()).filter(Boolean).slice(-2).join(" ").slice(0, 180);
}

// ---- SANDBOX synthetic detection --------------------------------------------
function synthResult(host: string, withDbCreds: boolean): DetectResult {
  const webRoots: DetectedWebRoot[] = [
    { path: "/var/www/html", type: "wordpress", sizeBytes: 512 * 1024 * 1024, sizeLabel: humanSize(512 * 1024 * 1024) },
    { path: "/home/deploy/public_html", type: "laravel", sizeBytes: 138 * 1024 * 1024, sizeLabel: humanSize(138 * 1024 * 1024) },
    { path: "/srv/www/api", type: "node", sizeBytes: 46 * 1024 * 1024, sizeLabel: humanSize(46 * 1024 * 1024) },
  ];
  const homes: DetectedHome[] = [
    { path: "/home/deploy", sizeBytes: 220 * 1024 * 1024, sizeLabel: humanSize(220 * 1024 * 1024) },
    { path: "/root", sizeBytes: 12 * 1024 * 1024, sizeLabel: humanSize(12 * 1024 * 1024) },
  ];
  const engines: DetectedEngine[] = [
    { engine: "mysql", present: true, listening: true, credentialsUsed: withDbCreds, note: withDbCreds ? undefined : "MySQL/MariaDB detected — add a database password to include databases." },
    { engine: "postgres", present: false, listening: false, credentialsUsed: false, note: "PostgreSQL not detected on this server." },
  ];
  const databases: DetectedDatabase[] = withDbCreds
    ? [
        { engine: "mysql", name: "wordpress", user: "root", sizeBytes: 84 * 1024 * 1024, sizeLabel: humanSize(84 * 1024 * 1024) },
        { engine: "mysql", name: "app_prod", user: "root", sizeBytes: 41 * 1024 * 1024, sizeLabel: humanSize(41 * 1024 * 1024) },
      ]
    : [];
  return {
    webRoots,
    homes,
    databases,
    engines: engines.filter((e) => e.present || e.listening || e.engine === "postgres"),
    notes: [`Staging sandbox: showing example detection results for ${host} (no real server was contacted).`],
  };
}
